<script setup>
import { onMounted, reactive, ref } from 'vue';import { ElMessage } from 'element-plus';import { listDocuments,reviewDocument,downloadDocument } from '../../api/document';import { saveDownload } from '../../utils/download';import { text,tagType,formatDate } from '../../utils/enums';import PageHeader from '../../components/PageHeader.vue';import AppPagination from '../../components/AppPagination.vue';import { messageOf } from '../../utils/request'
const state=reactive({list:[],total:0,pageNum:1,pageSize:10,reviewStatus:'PENDING',loading:false});const open=ref(false);const current=ref({});const form=reactive({reviewResult:'APPROVED',reviewComment:''});const load=async()=>{state.loading=true;try{const r=await listDocuments({pageNum:state.pageNum,pageSize:state.pageSize,reviewStatus:state.reviewStatus||undefined});state.list=r.data.list;state.total=r.data.total}finally{state.loading=false}};const show=row=>{current.value=row;open.value=true};const review=async()=>{try{await reviewDocument({targetType:current.value.documentType==='SUPPLEMENT'?'SUPPLEMENT':'DOCUMENT',targetId:current.value.id,...form});ElMessage.success('文件审核完成');open.value=false;load()}catch(e){ElMessage.error(messageOf(e))}};const download=async(row)=>{try{saveDownload(await downloadDocument(row.id),row.documentName)}catch(e){ElMessage.error(messageOf(e,'下载失败'))}};onMounted(load)
</script>
<template><div class="page"><PageHeader title="文件审核" description="审核申请文件、答复文件及补充材料"/><div class="toolbar"><el-select v-model="state.reviewStatus" placeholder="审核状态" clearable @change="load"><el-option label="待审核" value="PENDING"/><el-option label="已通过" value="APPROVED"/><el-option label="需重新提交" value="RESUBMIT_REQUIRED"/></el-select></div><div class="table-wrap"><el-table v-loading="state.loading" :data="state.list"><el-table-column prop="documentName" label="文件名" min-width="230"/><el-table-column prop="caseId" label="案件 ID" width="90"/><el-table-column label="类型" width="140"><template #default="{row}">{{text('documentType',row.documentType)}}</template></el-table-column><el-table-column label="审核状态" width="120"><template #default="{row}"><el-tag :type="tagType(row.reviewStatus)">{{text('reviewStatus',row.reviewStatus)}}</el-tag></template></el-table-column><el-table-column label="上传时间" width="160"><template #default="{row}">{{formatDate(row.createTime)}}</template></el-table-column><el-table-column width="140"><template #default="{row}"><el-button link @click="download(row)">下载</el-button><el-button v-if="row.reviewStatus==='PENDING'" link type="primary" @click="show(row)">审核</el-button></template></el-table-column></el-table></div><AppPagination v-model:page="state.pageNum" v-model:size="state.pageSize" :total="state.total" @change="load"/><el-dialog v-model="open" title="文件审核" width="min(520px,94vw)"><p class="dialog-lead">{{current.documentName}}</p><el-form label-position="top"><el-form-item label="审核结果"><el-select v-model="form.reviewResult"><el-option label="通过" value="APPROVED"/><el-option label="小幅修改" value="MINOR_REVISION"/><el-option label="重大修改" value="MAJOR_REVISION"/><el-option label="拒绝" value="REJECTED"/><el-option label="重新提交" value="RESUBMIT_REQUIRED"/></el-select></el-form-item><el-form-item label="审核意见"><el-input v-model="form.reviewComment" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" @click="review">保存结果</el-button></template></el-dialog></div></template>
